  59|// AntigravityExecutor proxies requests to the antigravity upstream.
  60|type AntigravityExecutor struct {
  61|	cfg *config.Config
  62|}
  63|
  64|// NewAntigravityExecutor creates a new Antigravity executor instance.
  65|//
  66|// Parameters:
  67|//   - cfg: The application configuration
  68|//
  69|// Returns:
  70|//   - *AntigravityExecutor: A new Antigravity executor instance
  71|func NewAntigravityExecutor(cfg *config.Config) *AntigravityExecutor {
  72|	return &AntigravityExecutor{cfg: cfg}
  73|}
  74|
  75|// Identifier returns the executor identifier.
  76|func (e *AntigravityExecutor) Identifier() string { return antigravityAuthType }
  77|
  78|// PrepareRequest injects Antigravity credentials into the outgoing HTTP request.
  79|func (e *AntigravityExecutor) PrepareRequest(req *http.Request, auth *cliproxyauth.Auth) error {
  80|	if req == nil {
  81|		return nil
  82|	}
  83|	token, _, errToken := e.ensureAccessToken(req.Context(), auth)
  84|	if errToken != nil {
  85|		return errToken
  86|	}
  87|	if strings.TrimSpace(token) == "" {
  88|		return statusErr{code: http.StatusUnauthorized, msg: "missing access token"}
  89|	}
  90|	req.Header.Set("Authorization", "Bearer "+token)
  91|	return nil
  92|}
  93|
  94|// HttpRequest injects Antigravity credentials into the request and executes it.
  95|func (e *AntigravityExecutor) HttpRequest(ctx context.Context, auth *cliproxyauth.Auth, req *http.Request) (*http.Response, error) {
  96|	if req == nil {
  97|		return nil, fmt.Errorf("antigravity executor: request is nil")
  98|	}
  99|	if ctx == nil {
 100|		ctx = req.Context()
 101|	}
 102|	httpReq := req.WithContext(ctx)
 103|	if err := e.PrepareRequest(httpReq, auth); err != nil {
 104|		return nil, err
 105|	}
 106|	httpClient := newProxyAwareHTTPClient(ctx, e.cfg, auth, 0)
 107|	return httpClient.Do(httpReq)
