 150|	var lastStatus int
 151|	var lastBody []byte
 152|	var lastErr error
 153|
 154|	for idx, baseURL := range baseURLs {
 155|		httpReq, errReq := e.buildRequest(ctx, auth, token, baseModel, translated, false, opts.Alt, baseURL)
 156|		if errReq != nil {
 157|			err = errReq
 158|			return resp, err
 159|		}
 160|
 161|		httpResp, errDo := httpClient.Do(httpReq)
 162|		if errDo != nil {
 163|			recordAPIResponseError(ctx, e.cfg, errDo)
 164|			if errors.Is(errDo, context.Canceled) || errors.Is(errDo, context.DeadlineExceeded) {
 165|				return resp, errDo
 166|			}
 167|			lastStatus = 0
 168|			lastBody = nil
 169|			lastErr = errDo
 170|			if idx+1 < len(baseURLs) {
 171|				log.Debugf("antigravity executor: request error on base url %s, retrying with fallback base url: %s", baseURL, baseURLs[idx+1])
 172|				continue
 173|			}
 174|			err = errDo
 175|			return resp, err
 176|		}
 177|
 178|		recordAPIResponseMetadata(ctx, e.cfg, httpResp.StatusCode, httpResp.Header.Clone())
 179|		bodyBytes, errRead := io.ReadAll(httpResp.Body)
 180|		if errClose := httpResp.Body.Close(); errClose != nil {
 181|			log.Errorf("antigravity executor: close response body error: %v", errClose)
 182|		}
 183|		if errRead != nil {
 184|			recordAPIResponseError(ctx, e.cfg, errRead)
 185|			err = errRead
 186|			return resp, err
 187|		}
 188|		appendAPIResponseChunk(ctx, e.cfg, bodyBytes)
 189|
 190|		if httpResp.StatusCode < http.StatusOK || httpResp.StatusCode >= http.StatusMultipleChoices {
 191|			log.Debugf("antigravity executor: upstream error status: %d, body: %s", httpResp.StatusCode, summarizeErrorBody(httpResp.Header.Get("Content-Type"), bodyBytes))
 192|			lastStatus = httpResp.StatusCode
 193|			lastBody = append([]byte(nil), bodyBytes...)
 194|			lastErr = nil
 195|			if httpResp.StatusCode == http.StatusTooManyRequests && idx+1 < len(baseURLs) {
 196|				log.Debugf("antigravity executor: rate limited on base url %s, retrying with fallback base url: %s", baseURL, baseURLs[idx+1])
 197|				continue
 198|			}
 199|			sErr := statusErr{code: httpResp.StatusCode, msg: string(bodyBytes)}
 200|			if httpResp.StatusCode == http.StatusTooManyRequests {
 201|				if retryAfter, parseErr := parseRetryDelay(bodyBytes); parseErr == nil && retryAfter != nil {
 202|					sErr.retryAfter = retryAfter
 203|				}
 204|			}
 205|			err = sErr
 206|			return resp, err
 207|		}
 208|
 209|		reporter.publish(ctx, parseAntigravityUsage(bodyBytes))
 210|		var param any
 211|		converted := sdktranslator.TranslateNonStream(ctx, to, from, req.Model, bytes.Clone(opts.OriginalRequest), translated, bodyBytes, &param)
 212|		resp = cliproxyexecutor.Response{Payload: []byte(converted)}
 213|		reporter.ensurePublished(ctx)
 214|		return resp, nil
 215|	}
 216|
 217|	switch {
 218|	case lastStatus != 0:
 219|		sErr := statusErr{code: lastStatus, msg: string(lastBody)}
 220|		if lastStatus == http.StatusTooManyRequests {
 221|			if retryAfter, parseErr := parseRetryDelay(lastBody); parseErr == nil && retryAfter != nil {
 222|				sErr.retryAfter = retryAfter
 223|			}
 224|		}
 225|		err = sErr
 226|	case lastErr != nil:
 227|		err = lastErr
 228|	default:
 229|		err = statusErr{code: http.StatusServiceUnavailable, msg: "antigravity executor: no base url available"}
 230|	}
 231|	return resp, err
