 459|func (e *AntigravityExecutor) convertStreamToNonStream(stream []byte) []byte {
 460|	responseTemplate := ""
 461|	var traceID string
 462|	var finishReason string
 463|	var modelVersion string
 464|	var responseID string
 465|	var role string
 466|	var usageRaw string
 467|	parts := make([]map[string]interface{}, 0)
 468|	var pendingKind string
 469|	var pendingText strings.Builder
 470|	var pendingThoughtSig string
 471|
 472|	flushPending := func() {
 473|		if pendingKind == "" {
 474|			return
 475|		}
 476|		text := pendingText.String()
 477|		switch pendingKind {
 478|		case "text":
 479|			if strings.TrimSpace(text) == "" {
 480|				pendingKind = ""
 481|				pendingText.Reset()
 482|				pendingThoughtSig = ""
 483|				return
 484|			}
 485|			parts = append(parts, map[string]interface{}{"text": text})
 486|		case "thought":
 487|			if strings.TrimSpace(text) == "" && pendingThoughtSig == "" {
 488|				pendingKind = ""
 489|				pendingText.Reset()
 490|				pendingThoughtSig = ""
 491|				return
 492|			}
 493|			part := map[string]interface{}{"thought": true}
 494|			part["text"] = text
 495|			if pendingThoughtSig != "" {
 496|				part["thoughtSignature"] = pendingThoughtSig
 497|			}
 498|			parts = append(parts, part)
 499|		}
 500|		pendingKind = ""
 501|		pendingText.Reset()
 502|		pendingThoughtSig = ""
 503|	}
 504|
 505|	normalizePart := func(partResult gjson.Result) map[string]interface{} {
 506|		var m map[string]interface{}
 507|		_ = json.Unmarshal([]byte(partResult.Raw), &m)
 508|		if m == nil {
 509|			m = map[string]interface{}{}
 510|		}
 511|		sig := partResult.Get("thoughtSignature").String()
 512|		if sig == "" {
 513|			sig = partResult.Get("thought_signature").String()
 514|		}
 515|		if sig != "" {
 516|			m["thoughtSignature"] = sig
 517|			delete(m, "thought_signature")
 518|		}
 519|		if inlineData, ok := m["inline_data"]; ok {
 520|			m["inlineData"] = inlineData
 521|			delete(m, "inline_data")
 522|		}
 523|		return m
 524|	}
 525|
 526|	for _, line := range bytes.Split(stream, []byte("\n")) {
 527|		trimmed := bytes.TrimSpace(line)
 528|		if len(trimmed) == 0 || !gjson.ValidBytes(trimmed) {
 529|			continue
 530|		}
 531|
 532|		root := gjson.ParseBytes(trimmed)
 533|		responseNode := root.Get("response")
 534|		if !responseNode.Exists() {
 535|			if root.Get("candidates").Exists() {
 536|				responseNode = root
 537|			} else {
 538|				continue
 539|			}
 540|		}
 541|		responseTemplate = responseNode.Raw
 542|
 543|		if traceResult := root.Get("traceId"); traceResult.Exists() && traceResult.String() != "" {
 544|			traceID = traceResult.String()
 545|		}
 546|
 547|		if roleResult := responseNode.Get("candidates.0.content.role"); roleResult.Exists() {
 548|			role = roleResult.String()
 549|		}
 550|
 551|		if finishResult := responseNode.Get("candidates.0.finishReason"); finishResult.Exists() && finishResult.String() != "" {
 552|			finishReason = finishResult.String()
 553|		}
 554|
 555|		if modelResult := responseNode.Get("modelVersion"); modelResult.Exists() && modelResult.String() != "" {
 556|			modelVersion = modelResult.String()
 557|		}
 558|		if responseIDResult := responseNode.Get("responseId"); responseIDResult.Exists() && responseIDResult.String() != "" {
 559|			responseID = responseIDResult.String()
