 466|		if pendingKind == "" {
 467|			return
 468|		}
 469|		text := pendingText.String()
 470|		switch pendingKind {
 471|		case "text":
 472|			if strings.TrimSpace(text) == "" {
 473|				pendingKind = ""
 474|				pendingText.Reset()
 475|				pendingThoughtSig = ""
 476|				return
 477|			}
 478|			parts = append(parts, map[string]interface{}{"text": text})
 479|		case "thought":
 480|			if strings.TrimSpace(text) == "" && pendingThoughtSig == "" {
 481|				pendingKind = ""
 482|				pendingText.Reset()
 483|				pendingThoughtSig = ""
 484|				return
 485|			}
 486|			part := map[string]interface{}{"thought": true}
 487|			part["text"] = text
 488|			if pendingThoughtSig != "" {
 489|				part["thoughtSignature"] = pendingThoughtSig
 490|			}
 491|			parts = append(parts, part)
 492|		}
 493|		pendingKind = ""
 494|		pendingText.Reset()
 495|		pendingThoughtSig = ""
 496|	}
