 501|		if m == nil {
 502|			m = map[string]interface{}{}
 503|		}
 504|		sig := partResult.Get("thoughtSignature").String()
 505|		if sig == "" {
 506|			sig = partResult.Get("thought_signature").String()
 507|		}
 508|		if sig != "" {
 509|			m["thoughtSignature"] = sig
 510|			delete(m, "thought_signature")
 511|		}
 512|		if inlineData, ok := m["inline_data"]; ok {
 513|			m["inlineData"] = inlineData
 514|			delete(m, "inline_data")
 515|		}
 516|		return m
 517|	}
 518|
 519|	for _, line := range bytes.Split(stream, []byte("\n")) {
 520|		trimmed := bytes.TrimSpace(line)
 521|		if len(trimmed) == 0 || !gjson.ValidBytes(trimmed) {
 522|			continue
 523|		}
 524|
 525|		root := gjson.ParseBytes(trimmed)
 526|		responseNode := root.Get("response")
 527|		if !responseNode.Exists() {
 528|			if root.Get("candidates").Exists() {
 529|				responseNode = root
 530|			} else {
 531|				continue
 532|			}
 533|		}
 534|		responseTemplate = responseNode.Raw
 535|
 536|		if traceResult := root.Get("traceId"); traceResult.Exists() && traceResult.String() != "" {
 537|			traceID = traceResult.String()
 538|		}
 539|
 540|		if roleResult := responseNode.Get("candidates.0.content.role"); roleResult.Exists() {
 541|			role = roleResult.String()
 542|		}
 543|
 544|		if finishResult := responseNode.Get("candidates.0.finishReason"); finishResult.Exists() && finishResult.String() != "" {
 545|			finishReason = finishResult.String()
 546|		}
 547|
 548|		if modelResult := responseNode.Get("modelVersion"); modelResult.Exists() && modelResult.String() != "" {
 549|			modelVersion = modelResult.String()
 550|		}
 551|		if responseIDResult := responseNode.Get("responseId"); responseIDResult.Exists() && responseIDResult.String() != "" {
 552|			responseID = responseIDResult.String()
 553|		}
 554|		if usageResult := responseNode.Get("usageMetadata"); usageResult.Exists() {
 555|			usageRaw = usageResult.Raw
 556|		} else if usageMetadataResult := root.Get("usageMetadata"); usageMetadataResult.Exists() {
 557|			usageRaw = usageMetadataResult.Raw
 558|		}
 559|
 560|		if partsResult := responseNode.Get("candidates.0.content.parts"); partsResult.IsArray() {
 561|			for _, part := range partsResult.Array() {
 562|				hasFunctionCall := part.Get("functionCall").Exists()
 563|				hasInlineData := part.Get("inlineData").Exists() || part.Get("inline_data").Exists()
 564|				sig := part.Get("thoughtSignature").String()
 565|				if sig == "" {
 566|					sig = part.Get("thought_signature").String()
 567|				}
 568|				text := part.Get("text").String()
 569|				thought := part.Get("thought").Bool()
 570|
 571|				if hasFunctionCall || hasInlineData {
 572|					flushPending()
