 608|	}
 609|	if finishReason != "" {
 610|		responseTemplate, _ = sjson.Set(responseTemplate, "candidates.0.finishReason", finishReason)
 611|	}
 612|	if modelVersion != "" {
 613|		responseTemplate, _ = sjson.Set(responseTemplate, "modelVersion", modelVersion)
 614|	}
 615|	if responseID != "" {
 616|		responseTemplate, _ = sjson.Set(responseTemplate, "responseId", responseID)
 617|	}
 618|	if usageRaw != "" {
 619|		responseTemplate, _ = sjson.SetRaw(responseTemplate, "usageMetadata", usageRaw)
 620|	} else if !gjson.Get(responseTemplate, "usageMetadata").Exists() {
 621|		responseTemplate, _ = sjson.Set(responseTemplate, "usageMetadata.promptTokenCount", 0)
 622|		responseTemplate, _ = sjson.Set(responseTemplate, "usageMetadata.candidatesTokenCount", 0)
 623|		responseTemplate, _ = sjson.Set(responseTemplate, "usageMetadata.totalTokenCount", 0)
 624|	}
 625|
 626|	output := `{"response":{},"traceId":""}`
 627|	output, _ = sjson.SetRaw(output, "response", responseTemplate)
 628|	if traceID != "" {
 629|		output, _ = sjson.Set(output, "traceId", traceID)
 630|	}
